WITH base AS (SELECT * FROM products WHERE ARRAY_CONTAINS(tags, 'premium') AND LOWER(product_name) LIKE '%ack%' AND MONTH(launch_date) IN (5, 6, 12)), agg AS (SELECT category, CASE WHEN cost >= 620 THEN 'high' WHEN cost >= 270 THEN 'mid' ELSE 'low' END cost_bucket, MAX(cost) max_cost, ROUND((100 * SUM(CASE WHEN category = 'Books' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_books FROM base GROUP BY category, CASE WHEN cost >= 620 THEN 'high' WHEN cost >= 270 THEN 'mid' ELSE 'low' END) SELECT category, cost_bucket, max_cost, pct_books FROM agg WHERE max_cost > 690 ORDER BY cost_bucket
